import os
import torch


class Config:
    """
    Configuration class for the GC-CGCNN pipeline.
    """

    # -------------------------------------------------------------------------
    # Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # File Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the analysis script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Working directory for this specific experiment/idea
    WORKING_DIR = "./working/idea_5"

    # Cache directory for processed graphs
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # Model checkpoint location
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    BEST_MODEL_PATH = os.path.join(CHECKPOINT_DIR, "best_model.pth")

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # -------------------------------------------------------------------------
    # Data Processing Hyperparameters
    # -------------------------------------------------------------------------
    # Cutoff radius for neighbor search in Angstroms
    CUTOFF_RADIUS = 5.0

    # Maximum number of neighbors to consider per atom (for tensor sizing efficiency)
    MAX_NEIGHBORS = 50

    # Target column names in the CSV files
    TARGET_COLS = ["formation_energy_ev_natom", "bandgap_energy_ev"]

    # Features to extract for the global conditioning vector
    # 6 Lattice parameters (lengths a,b,c, angles alpha,beta,gamma) + 4 Composition fractions
    GLOBAL_FEATURE_COLS = [
        "lattice_vector_1_ang",
        "lattice_vector_2_ang",
        "lattice_vector_3_ang",
        "lattice_angle_alpha_degree",
        "lattice_angle_beta_degree",
        "lattice_angle_gamma_degree",
        "percent_atom_al",
        "percent_atom_ga",
        "percent_atom_in",
        "number_of_total_atoms",
        # Note: number_of_total_atoms is used as a proxy for O fraction or density context
    ]

    # Maximum atomic number to support in embeddings (In is 49, so 100 is safe)
    MAX_ATOMIC_NUMBER = 100

    # -------------------------------------------------------------------------
    # Model Hyperparameters (GC-CGCNN)
    # -------------------------------------------------------------------------
    # Dimension of atom (node) embeddings
    ATOM_EMBEDDING_DIM = 64

    # Dimension of edge embeddings (expanded distances)
    EDGE_EMBEDDING_DIM = 64

    # Dimension of the global feature vector (must match len(GLOBAL_FEATURE_COLS))
    GLOBAL_INPUT_DIM = 10

    # Number of RBF bins for expanding interatomic distances
    RBF_BINS = 60
    RBF_MIN = 0.0
    RBF_MAX = 5.0

    # Number of FiLM-CGCNN interaction blocks
    NUM_FILM_BLOCKS = 4

    # Hidden dimension for internal MLPs
    MLP_HIDDEN_DIM = 64

    # Dropout rate for regularization
    DROPOUT_RATE = 0.1

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 48
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    NUM_EPOCHS = 150

    # Early stopping configuration
    EARLY_STOPPING_PATIENCE = 20

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # -------------------------------------------------------------------------
    # Debugging / Development
    # -------------------------------------------------------------------------
    # Set to True to use a small subset of data for quick pipeline testing
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 100

    @classmethod
    def setup(cls):
        """
        Creates necessary directories for the experiment.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.CHECKPOINT_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        print(f"Directories initialized at {cls.WORKING_DIR}")
